CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agencies (id text PRIMARY KEY, name text NOT NULL, verification text NOT NULL DEFAULT 'sample-unverified', is_sample boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE buildings (id text PRIMARY KEY, name text NOT NULL, agency_id text NOT NULL REFERENCES agencies(id), is_sample boolean NOT NULL DEFAULT false);
CREATE TABLE floors (id text PRIMARY KEY, name text NOT NULL, building_id text NOT NULL REFERENCES buildings(id), is_sample boolean NOT NULL DEFAULT false);
CREATE TABLE divisions (id text PRIMARY KEY, name text NOT NULL, short_name text NOT NULL DEFAULT '', agency_id text NOT NULL REFERENCES agencies(id), is_sample boolean NOT NULL DEFAULT false);
CREATE TABLE rooms (id text PRIMARY KEY, name text NOT NULL, floor_id text NOT NULL REFERENCES floors(id), width double precision NOT NULL CHECK(width>0), depth double precision NOT NULL CHECK(depth>0), is_sample boolean NOT NULL DEFAULT false);
CREATE TABLE division_room_links (id text PRIMARY KEY, division_id text NOT NULL REFERENCES divisions(id), room_id text NOT NULL REFERENCES rooms(id), UNIQUE(division_id,room_id));
CREATE TABLE organizational_departments (id text PRIMARY KEY, name text NOT NULL, division_id text NOT NULL REFERENCES divisions(id), is_sample boolean NOT NULL DEFAULT false);
CREATE TABLE areas (id text PRIMARY KEY, name text NOT NULL, kind text NOT NULL DEFAULT 'custom', description text NOT NULL DEFAULT '', room_id text NOT NULL REFERENCES rooms(id), division_id text NOT NULL REFERENCES divisions(id), department_id text REFERENCES organizational_departments(id), width double precision NOT NULL DEFAULT 4 CHECK(width>0), depth double precision NOT NULL DEFAULT 3 CHECK(depth>0), is_sample boolean NOT NULL DEFAULT false);
CREATE TABLE personnel (id text PRIMARY KEY, rank text NOT NULL DEFAULT '', first_name text NOT NULL, last_name text NOT NULL, division_id text NOT NULL REFERENCES divisions(id), department_id text REFERENCES organizational_departments(id), position_title text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, is_sample boolean NOT NULL DEFAULT false);
CREATE TABLE asset_categories (id text PRIMARY KEY, parent_id text REFERENCES asset_categories(id), code text NOT NULL UNIQUE, name text NOT NULL, icon text NOT NULL DEFAULT 'box', default_width double precision NOT NULL DEFAULT 0.8 CHECK(default_width>0), default_depth double precision NOT NULL DEFAULT 0.6 CHECK(default_depth>0), active boolean NOT NULL DEFAULT true, CHECK(parent_id IS DISTINCT FROM id));
CREATE TABLE assets (id text PRIMARY KEY, asset_number text NOT NULL UNIQUE CHECK(asset_number ~ '^7[0-9]{3}\.[0-9]{4}\.[0-9]{3}\.[0-9]{3}\.[0-9]{2}$'), name text NOT NULL, category_id text NOT NULL REFERENCES asset_categories(id), area_id text REFERENCES areas(id), custodian_id text REFERENCES personnel(id), user_id text REFERENCES personnel(id), division_id text NOT NULL REFERENCES divisions(id), department_id text REFERENCES organizational_departments(id), brand text NOT NULL DEFAULT '', model text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'ใช้งาน' CHECK(status IN ('ใช้งาน','ชำรุด','ซ่อม','รอตรวจสอบ','จำหน่าย')), condition text NOT NULL DEFAULT '', purchase_date date, purchase_price numeric CHECK(purchase_price>=0), notes text NOT NULL DEFAULT '', is_sample boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION immutable_asset_number() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.asset_number <> OLD.asset_number THEN RAISE EXCEPTION 'asset_number is immutable' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER asset_number_immutable BEFORE UPDATE ON assets FOR EACH ROW EXECUTE FUNCTION immutable_asset_number();
CREATE TABLE layouts (id text PRIMARY KEY, room_id text UNIQUE REFERENCES rooms(id), area_id text UNIQUE REFERENCES areas(id), width double precision NOT NULL CHECK(width>0), depth double precision NOT NULL CHECK(depth>0), orientation text NOT NULL DEFAULT 'landscape' CHECK(orientation IN ('landscape','portrait')), objects jsonb NOT NULL DEFAULT '[]', published_objects jsonb NOT NULL DEFAULT '[]', settings jsonb NOT NULL DEFAULT '{}', revision integer NOT NULL DEFAULT 1, published_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), CHECK((room_id IS NULL) <> (area_id IS NULL)));
CREATE VIEW master_layouts AS SELECT * FROM layouts WHERE room_id IS NOT NULL;
CREATE VIEW detail_layouts AS SELECT * FROM layouts WHERE area_id IS NOT NULL;
CREATE TABLE fixtures (id text PRIMARY KEY, fixture_code text NOT NULL UNIQUE, name text NOT NULL, area_id text NOT NULL REFERENCES areas(id), is_sample boolean NOT NULL DEFAULT false);
CREATE TABLE asset_movements (id text PRIMARY KEY, asset_id text NOT NULL REFERENCES assets(id), from_area_id text REFERENCES areas(id), to_area_id text REFERENCES areas(id), from_person_id text REFERENCES personnel(id), to_person_id text REFERENCES personnel(id), changed_by text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE asset_assignment_history (id text PRIMARY KEY, asset_id text NOT NULL REFERENCES assets(id), person_id text REFERENCES personnel(id), assigned_from timestamptz NOT NULL DEFAULT now(), assigned_to timestamptz, changed_by text NOT NULL, reason text NOT NULL);
CREATE TABLE user_accounts (id text PRIMARY KEY, username text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','editor','viewer','auditor')), active boolean NOT NULL DEFAULT true, is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES user_accounts(id), expires_at timestamptz NOT NULL);
CREATE TABLE audit_logs (id text PRIMARY KEY, actor text NOT NULL, action text NOT NULL, entity text NOT NULL, entity_id text NOT NULL, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE view_presets (id text PRIMARY KEY, name text NOT NULL, filters jsonb NOT NULL DEFAULT '{}');
CREATE TABLE sync_state (id text PRIMARY KEY, synced_at timestamptz, last_error text, pending boolean NOT NULL DEFAULT true);
INSERT INTO sync_state(id) VALUES('google_sheets');
CREATE INDEX assets_area_idx ON assets(area_id);
CREATE INDEX assets_custodian_idx ON assets(custodian_id);
CREATE INDEX audit_created_idx ON audit_logs(created_at);
